"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[66255],{3331:(i,e,a)=>{a.d(e,{R:()=>r,x:()=>l});var o=a(36672);const n={},t=o.createContext(n);function r(i){const e=o.useContext(t);return o.useMemo((function(){return"function"==typeof i?i(e):{...e,...i}}),[e,i])}function l(i){let e;return e=i.disableParentContext?"function"==typeof i.components?i.components(n):i.components||n:r(i.components),o.createElement(t.Provider,{value:e},i.children)}},57398:(i,e,a)=>{a.r(e),a.d(e,{assets:()=>s,contentTitle:()=>l,default:()=>u,frontMatter:()=>r,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"2023/04/11","title":"2023-04-11","description":"Microsoft corregge un bug di Defender vecchio di 5 anni, riducendo l\'utilizzo della CPU di Firefox del 75%.","source":"@site/i18n/it/docusaurus-plugin-content-docs/current/2023/04/11.md","sourceDirName":"2023/04","slug":"/2023/04/11","permalink":"/it/2023/04/11","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/it/docusaurus-plugin-content-docs//current/2023/04/11.md","tags":[],"version":"current","frontMatter":{"localized_date":"11 aprile 2023","top_news":"Microsoft corregge un bug di Defender vecchio di 5 anni, riducendo l\'utilizzo della CPU di Firefox del 75%."},"sidebar":"defaultSidebar","previous":{"title":"2023-04-12","permalink":"/it/2023/04/12"},"next":{"title":"2023-04-10","permalink":"/it/2023/04/10"}}');var n=a(23420),t=a(3331);const r={localized_date:"11 aprile 2023",top_news:"Microsoft corregge un bug di Defender vecchio di 5 anni, riducendo l'utilizzo della CPU di Firefox del 75%."},l="2023-04-11",s={},c=[{value:"Microsoft corregge un bug di Defender vecchio di 5 anni, riducendo l&#39;utilizzo della CPU di Firefox del 75%.",id:"microsoft-corregge-un-bug-di-defender-vecchio-di-5-anni-riducendo-lutilizzo-della-cpu-di-firefox-del-75",level:2},{value:"Animazione in continua espansione della vita del 796\xb0 piano di una stazione spaziale.",id:"animazione-in-continua-espansione-della-vita-del-796-piano-di-una-stazione-spaziale",level:2},{value:"Night of the living brain fog dead o come mi sono migliorato con l&#39;open source",id:"night-of-the-living-brain-fog-dead-o-come-mi-sono-migliorato-con-lopen-source",level:2},{value:"RePalm",id:"repalm",level:2},{value:"Ripetizione distanziata efficace",id:"ripetizione-distanziata-efficace",level:2},{value:"Il pi\xf9 grande impianto di riciclaggio di batterie per veicoli elettrici degli Stati Uniti \xe8 aperto al pubblico",id:"il-pi\xf9-grande-impianto-di-riciclaggio-di-batterie-per-veicoli-elettrici-degli-stati-uniti-\xe8-aperto-al-pubblico",level:2},{value:"FTX ha conservato le chiavi private delle attivit\xe0 crittografiche in chiaro, senza controlli di accesso.",id:"ftx-ha-conservato-le-chiavi-private-delle-attivit\xe0-crittografiche-in-chiaro-senza-controlli-di-accesso",level:2},{value:"Ho riparato uno scarico parassita sulla mia auto in 408 giorni",id:"ho-riparato-uno-scarico-parassita-sulla-mia-auto-in-408-giorni",level:2},{value:"Come iniziare a saldare",id:"come-iniziare-a-saldare",level:2},{value:"Insegnare a ChatGPT a parlare la lingua inventata di mio figlio",id:"insegnare-a-chatgpt-a-parlare-la-lingua-inventata-di-mio-figlio",level:2},{value:"\xc8 morto Al Jaffee, il re del fold-in di Mad Magazine.",id:"\xe8-morto-al-jaffee-il-re-del-fold-in-di-mad-magazine",level:2},{value:"L&#39;inferno non finisce mai su x86: La storia dell&#39;iperspazio, continua, pi\xf9 o meno",id:"linferno-non-finisce-mai-su-x86-la-storia-delliperspazio-continua-pi\xf9-o-meno",level:2},{value:"Dobbiamo parlare di Vercel",id:"dobbiamo-parlare-di-vercel",level:2},{value:"I filmati delle dashcam mostrano le auto senza conducente che intasano San Francisco",id:"i-filmati-delle-dashcam-mostrano-le-auto-senza-conducente-che-intasano-san-francisco",level:2},{value:"OpenBSD 7.3",id:"openbsd-73",level:2},{value:"Personal Concierge con ChatGPT di OpenAI via Telegram e messaggi vocali",id:"personal-concierge-con-chatgpt-di-openai-via-telegram-e-messaggi-vocali",level:2},{value:"EditAnything: Segmento di qualsiasi cosa + ControlNet + BLIP2 + Diffusione stabile",id:"editanything-segmento-di-qualsiasi-cosa--controlnet--blip2--diffusione-stabile",level:2},{value:"Agenti generativi: Simulacri interattivi del comportamento umano",id:"agenti-generativi-simulacri-interattivi-del-comportamento-umano",level:2},{value:"Peste danzante del 1518",id:"peste-danzante-del-1518",level:2},{value:"I punteggi del QI americano sono rapidamente scesi, a riprova dell&#39;&quot;effetto Flynn inverso&quot;.",id:"i-punteggi-del-qi-americano-sono-rapidamente-scesi-a-riprova-delleffetto-flynn-inverso",level:2},{value:"Usare il PIO RP2040 per pilotare un displa mal progettato",id:"usare-il-pio-rp2040-per-pilotare-un-displa-mal-progettato",level:2},{value:"Algoritmo di classificazione di Hacker News",id:"algoritmo-di-classificazione-di-hacker-news",level:2},{value:"La chiusura dell&#39;energia nucleare potrebbe aumentare l&#39;inquinamento atmosferico: uno studio",id:"la-chiusura-dellenergia-nucleare-potrebbe-aumentare-linquinamento-atmosferico-uno-studio",level:2},{value:"Il crollo delle spedizioni di PC da parte di Apple \xe8 il pi\xf9 forte tra i principali produttori di computer",id:"il-crollo-delle-spedizioni-di-pc-da-parte-di-apple-\xe8-il-pi\xf9-forte-tra-i-principali-produttori-di-computer",level:2},{value:"Se hai raccolto capitale di rischio, devi pagarti da solo",id:"se-hai-raccolto-capitale-di-rischio-devi-pagarti-da-solo",level:2},{value:"Il fiume Kissimmee \xe8 stato riportato in vita e la fauna selvatica sta prosperando.",id:"il-fiume-kissimmee-\xe8-stato-riportato-in-vita-e-la-fauna-selvatica-sta-prosperando",level:2},{value:"Usare le azioni GitHub per rendere dinamico il profilo GitHub",id:"usare-le-azioni-github-per-rendere-dinamico-il-profilo-github",level:2},{value:"Quello che ho imparato sui metodi formali in mezzo anno",id:"quello-che-ho-imparato-sui-metodi-formali-in-mezzo-anno",level:2},{value:"LLM open source per uso commerciale?",id:"llm-open-source-per-uso-commerciale",level:2},{value:"Scatterplot animati e zoomabili nel browser, con una scala di oltre un miliardo di punti.",id:"scatterplot-animati-e-zoomabili-nel-browser-con-una-scala-di-oltre-un-miliardo-di-punti",level:2}];function d(i){const e={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,t.R)(),...i.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(e.header,{children:(0,n.jsx)(e.h1,{id:"2023-04-11",children:"2023-04-11"})}),"\n",(0,n.jsx)(e.h2,{id:"microsoft-corregge-un-bug-di-defender-vecchio-di-5-anni-riducendo-lutilizzo-della-cpu-di-firefox-del-75",children:"Microsoft corregge un bug di Defender vecchio di 5 anni, riducendo l'utilizzo della CPU di Firefox del 75%."}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://bugzilla.mozilla.org/show_bug.cgi?id=1441918",children:"Originale"}),".\nSpiacente, il testo fornito non \xe8 correlato al titolo o all'argomento dell'articolo. Puoi fornire il testo corretto?"]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35511713",children:"Discussion Service"}),".\nMicrosoft ha risolto un bug di Defender di 5 anni fa che riduceva l'utilizzo della CPU di Firefox. I prodotti antivirus hanno avuto un impatto sulla CPU simile, ma meno grave. Si discute dell'ottimizzazione delle piccole cose rispetto all'impronta di CO2. Gli utenti di Discussion Service discutono dell'efficienza energetica dei browser web, degli ad-blocker e della compatibilit\xe0 dei browser con Windows. La disattivazione della \"modalit\xe0 ambiente\" di YouTube su Firefox fa risparmiare il 30% di CPU su un Mac. Si discute di Mac e Linux per la risoluzione dei problemi. Critiche e suggerimenti per Firefox che genera un elevato utilizzo della CPU rispetto a Chrome. Si segnala un bug di ETW e un calo delle prestazioni di Defender nelle operazioni di PowerShell."]}),"\n",(0,n.jsx)(e.h2,{id:"animazione-in-continua-espansione-della-vita-del-796-piano-di-una-stazione-spaziale",children:"Animazione in continua espansione della vita del 796\xb0 piano di una stazione spaziale."}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://floor796.com/#t4r0,512,512",children:"Originale"}),".\n\xc8 stata creata un'animazione in continua espansione che mostra la vita del 796\xb0 piano di una stazione spaziale. Il progetto, denominato Floor796, \xe8 stato realizzato da un artista e da un programmatore e rappresenta una panoramica immaginaria della routine quotidiana di una stazione spaziale. L'animazione copre aree come l'agricoltura, le attivit\xe0 ricreative e gli esperimenti scientifici. I creatori sperano che il progetto ispiri e incoraggi le generazioni future a esplorare lo spazio e promuova una visione pi\xf9 ottimistica e positiva del futuro."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35510067",children:"Discussion Service"}),".\nUn'animazione della stazione spaziale animata a mano e open-source ha guadagnato un'attenzione virale per i suoi riferimenti alla cultura pop. Un utente di Discussion Service nota le allusioni storiche russe. Il progetto di animazione \xe8 un'iniziativa indipendente che evita l'uso eccessivo di framework e dipendenze. Gli utenti suggeriscono miglioramenti, ma alcuni difendono la creativit\xe0 dell'artista. L'editor di animazione utilizzato \xe8 consigliato come strumento utile."]}),"\n",(0,n.jsx)(e.h2,{id:"night-of-the-living-brain-fog-dead-o-come-mi-sono-migliorato-con-lopen-source",children:"Night of the living brain fog dead o come mi sono migliorato con l'open source"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://decodebytes.substack.com/p/night-of-the-living-brain-fog-dead",children:"Originale"}),".\nUn blogger condivide il suo percorso di utilizzo di software open source per gestire una grave apnea notturna dopo aver provato vari \"hack\" per l'igiene del sonno e aver ricevuto la prescrizione della CPAP. Scopre una comunit\xe0 online che utilizza il software open source OSCAR per approfondire le metriche del sonno e acquista un apparecchio che esporta i dati nel formato corretto. Un altro blogger raccomanda un servo-ventilatore adattivo (ASV) come trattamento pi\xf9 efficace per l'apnea centrale del sonno, con risultati positivi visti attraverso il ripristino dei modelli di respirazione e una sana ossigenazione del sangue. L'autore incoraggia gli altri a cercare un trattamento per l'apnea notturna non diagnosticata."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35511047",children:"Discussion Service"}),".\nIl viaggio di un individuo per affrontare i problemi di salute evidenzia la necessit\xe0 di farsi carico della salute invece di affidarsi esclusivamente ai sistemi medici tradizionali. Gli utenti di Discussion Service discutono i problemi e gli ostacoli legati all'aderenza del sistema medico a trattamenti comprovati e alla riluttanza ad adottare nuovi metodi. I pazienti non dovrebbero affidarsi esclusivamente a trattamenti non sperimentati e dovrebbero integrare le cure tradizionali. Gli utenti discutono del grado di rischio accettabile tra i diversi settori e dell'importanza di apparecchiature mediche aperte e dell'accessibilit\xe0 dei dati. Alcuni utenti riportano risultati contrastanti con i vari rimedi e metodi per il sonno. Il post discute le potenziali cause della \"nebbia cerebrale\" e l'importanza dei dispositivi medici aperti e della conoscenza. Racconto personale di un'esperienza positiva con il trattamento CPAP e discussione sulle alternative alla CPAP. Si parla anche di un canale YouTube che presenta dispositivi di monitoraggio della salute e della difficolt\xe0 di ottenere cure mediche e studi sul sonno. La diagnosi e il trattamento dell'apnea notturna possono essere lunghi e costosi. Gli esercizi di postura della lingua e i metodi di recupero personali possono aiutare a gestire i sintomi."]}),"\n",(0,n.jsx)(e.h2,{id:"repalm",children:"RePalm"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://dmitry.gr/?r=05.Projects&proj=27.%20rePalm",children:"Originale"}),".\nIl progetto rePalm di Dmitry.GR \xe8 un nuovo emulatore per PalmOS, che copre argomenti quali il supporto virtuale per le schede SD, la traduzione delle istruzioni ARM e altro ancora. Gli sviluppatori condividono informazioni sulle limitazioni hardware e sul loro superamento e forniscono un'immagine di anteprima di PalmOS 5.2.8 in esecuzione su una discovery board. I piani futuri prevedono l'implementazione di BT, WiFi, USB e il debug di NVFS. Gli aggiornamenti di rePalm includono correzioni e supporto per microfono/Zodiac per l'hardware reSpring v1.3.0.0. Una lettura tecnica per chi \xe8 interessato alle limitazioni hardware dei dispositivi del passato."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35511106",children:"Discussion Service"}),".\nUn nuovo post su Hacker News parla di RePalm e dei dispositivi Palm, con gli utenti che citano i modi specifici in cui li usano e alcuni che mettono in discussione il loro uso continuato. Alcuni utenti consigliano di utilizzare i brain dump nel coding per rimanere concentrati, mentre altri ricordano le caratteristiche uniche dei PDA non smartphone. Gli esperti analizzano i fattori che hanno portato alla scomparsa di PalmOS, tra cui gli errori di progettazione e le debolezze tecniche, mentre discutono della lentezza dei progressi e del valore dei risultati incrementali nei progetti tecnologici. Gli utenti esprimono nostalgia per i dispositivi tecnologici retr\xf2 come Palm e continuano a usarli nonostante la disponibilit\xe0 di nuove tecnologie. Un utente sta sviluppando una versione moderna di PalmOS e alcuni utenti suggeriscono che lo sviluppo di una tecnologia simile \xe8 pi\xf9 impegnativo rispetto alla media dei lavori di codifica."]}),"\n",(0,n.jsx)(e.h2,{id:"ripetizione-distanziata-efficace",children:"Ripetizione distanziata efficace"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://borretti.me/article/effective-spaced-repetition",children:"Originale"}),".\nUn post sull'efficacia della ripetizione distanziata per ricordare qualcosa sottolinea l'importanza di seguire le regole per la scrittura delle flashcard, tra cui capire prima, essere onesti, ripetere, organizzare per fonte, scrivere flashcard atomiche e fare domande in pi\xf9 modi. I fattori limitanti includono la formazione dell'abitudine e la capacit\xe0 di scrittura. Per conservare le informazioni, \xe8 necessario porre domande in direzione dall'alto verso il basso e dal basso verso l'alto e suddividere le flashcard pi\xf9 grandi in altre pi\xf9 piccole. Il post fornisce flashcard e script per la memorizzazione e incoraggia l'automazione. I tipi di note di Anki e la mancanza di questa funzione in Mochi sono l'obiettivo principale, con enfasi su concetti chiari, atomicit\xe0, semplicit\xe0 e ridondanza nelle flashcard. L'autore invita a fare offerte di lavoro per la scrittura di compilatori."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35511357",children:"Discussion Service"}),".\nUn articolo sulla ripetizione distanziata efficace invita gli utenti di Hacker News a condividere le loro esperienze e a fornire strumenti alternativi. Gli utenti offrono consigli per usare Anki in modo efficace e discutono i metodi per utilizzare la ripetizione spaziata in diversi campi. Alcuni utenti chiedono consigli per memorizzare argomenti specifici utilizzando SRS e flashcard. Mentre alcuni considerano le flashcard preconfezionate meno efficaci, altri sviluppano strumenti di automazione. Viene sottolineata l'importanza del tasso di richiamo nelle statistiche di Anki e viene sollevato il rischio di includere troppe informazioni nelle flashcard. Si sottolinea l'efficacia dei mazzi condivisi per gli studenti di medicina e si raccomanda un carattere che non intralci la lettura. Si parla anche di dislessia e dislessia parziale."]}),"\n",(0,n.jsx)(e.h2,{id:"il-pi\xf9-grande-impianto-di-riciclaggio-di-batterie-per-veicoli-elettrici-degli-stati-uniti-\xe8-aperto-al-pubblico",children:"Il pi\xf9 grande impianto di riciclaggio di batterie per veicoli elettrici degli Stati Uniti \xe8 aperto al pubblico"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.canarymedia.com/articles/recycling-renewables/the-biggest-ev-battery-recycling-plant-in-the-us-is-open-for-business",children:"Originale"}),".\nAscend Elements ha aperto a Covington, in Georgia, il pi\xf9 grande impianto di riciclaggio di batterie per veicoli elettrici (EV) del Nord America, in grado di trattare 30.000 tonnellate metriche di batterie agli ioni di litio usate all'anno. Gli impianti di riciclaggio potrebbero essere utilizzati per riciclare e riconvertire le batterie dei veicoli elettrici in modo economicamente vantaggioso, in modo da ottenere nuovi materiali per le batterie senza i costi e l'impatto ambientale di nuove estrazioni. Il governo statunitense cerca di rendere il Paese pi\xf9 capace di rifornirsi delle batterie che saranno parte integrante dell'elettrificazione dei trasporti e della decarbonizzazione della rete. Altre start-up di riciclaggio, come Redwood Materials e Li-Cycle, si sono unite a questo sforzo."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35513612",children:"Discussion Service"}),".\nIl pi\xf9 grande impianto di riciclaggio di batterie per veicoli elettrici degli Stati Uniti \xe8 operativo, creando un'alternativa pi\xf9 sostenibile alla produzione di nuovi materiali. Gli utenti di Discussion Service si informano sui processi di riciclaggio, sui costi di manodopera e sulla possibilit\xe0 di sostituire le batterie nei sistemi di stoccaggio stazionario di seconda vita. Nei commenti si discute della fattibilit\xe0 di treni da 20 vagoni, dei vantaggi economici dei sistemi di transito e dello stato attuale del riciclaggio del litio. Gli esperti riflettono sulla longevit\xe0 delle batterie EV e sui progressi della tecnologia delle batterie, mentre l'esclusivo processo di riciclaggio di Li-Cycle solleva dubbi sulla scalabilit\xe0 e sul valore dei sottoprodotti."]}),"\n",(0,n.jsx)(e.h2,{id:"ftx-ha-conservato-le-chiavi-private-delle-attivit\xe0-crittografiche-in-chiaro-senza-controlli-di-accesso",children:"FTX ha conservato le chiavi private delle attivit\xe0 crittografiche in chiaro, senza controlli di accesso."}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://twitter.com/molly0xFFF/status/1645217786698903559",children:"Original"}),".\nSecondo un rapporto di ZenGo, la borsa di criptovalute FTX ha conservato le chiavi private degli utenti in chiaro, senza controlli di accesso. Ci\xf2 significa che gli aggressori che accedono ai database di FTX possono facilmente rubare le chiavi private degli utenti e accedere ai loro fondi. ZenGo ha segnalato il problema a FTX, che ha provveduto a risolverlo. L'incidente sottolinea l'importanza di proteggere adeguatamente le chiavi private, necessarie per accedere e gestire le attivit\xe0 in criptovaluta. Inoltre, ricorda che anche le borse ben consolidate possono presentare vulnerabilit\xe0 che mettono a rischio i beni degli utenti."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35514294",children:"Discussion Service"}),".\nLa borsa di criptovalute FTX ha memorizzato le chiavi private in chiaro, causando preoccupazioni sulla sicurezza. Gli utenti di Discussion Service suggeriscono a FTX di utilizzare una crittografia asimmetrica e di fare difetto ai sistemi bancari tradizionali. Dibattito sull'uso della crittografia al di fuori del controllo governativo e sull'applicazione equa delle leggi. I protocolli di sicurezza di FTX vengono criticati; gli esperti suggeriscono portafogli caldi e freddi. I laptop confiscati ai dirigenti di FTX rivelano chiavi private in chiaro in Google Drive condiviso. L'incidente solleva interrogativi sulla gestione del rischio e sui requisiti di licenza per gli ingegneri software. Accuse a FTX di aver rubato i fondi dei clienti."]}),"\n",(0,n.jsx)(e.h2,{id:"ho-riparato-uno-scarico-parassita-sulla-mia-auto-in-408-giorni",children:"Ho riparato uno scarico parassita sulla mia auto in 408 giorni"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://davidmuller.github.io/posts/2023/04/10/how-i-fixed-a-parasitic-drain-in-408-days.html",children:"Originale"}),".\nUn proprietario di un'auto condivide la propria esperienza nel risolvere un persistente scarico parassita della batteria della propria Mazda3 hatchback del 2013, che ha richiesto 408 giorni per essere diagnosticato e risolto. Il problema faceva s\xec che la batteria si scaricasse da sola nel giro di ore o giorni ed \xe8 stato diagnosticato misurando le tensioni sui fusibili dell'auto per individuare i componenti che assorbivano energia quando l'auto era spenta. Il proprietario ha scollegato il sistema informatico del portachiavi per impedire lo scaricamento della batteria, che probabilmente funzionava male e teneva accesi per errore sistemi come il computer della trasmissione. Il proprietario avverte che il problema era intermittente e si \xe8 verificato anche dopo aver sostituito la batteria due volte, e consiglia di non eseguire esperimenti per cercare assorbimenti parassiti senza prima assicurarsi che l'auto sia chiusa a chiave con le portiere chiuse."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35513636",children:"Discussion Service"}),".\nUn utente di Hacker News ha risolto un problema di scaricamento parassita della batteria dell'auto causato da una portiera semichiusa, e altri hanno condiviso esperienze simili. La specializzazione nella risoluzione di problemi elettronici potrebbe essere vantaggiosa per i meccanici, ma ha un basso valore commerciale. Le discussioni riguardano la manutenzione della batteria dell'auto durante i periodi di inutilizzo, la risoluzione di problemi elettrici e consigli pratici ed esperienze relative alla manutenzione dell'auto. Alcuni utenti esprimono frustrazione per la complessit\xe0 delle auto moderne e per i componenti elettronici che possono essere difficili e costosi da riparare. Gli utenti propongono soluzioni pratiche, sostenibilit\xe0 a lungo termine e trasporti alternativi in citt\xe0 percorribili a piedi."]}),"\n",(0,n.jsx)(e.h2,{id:"come-iniziare-a-saldare",children:"Come iniziare a saldare"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.popularmechanics.com/technology/a43400768/how-to-get-started-in-soldering/",children:"Originale"}),".\nLa saldatura \xe8 un hobby accessibile e un'abilit\xe0 utile: il consiglio migliore \xe8 quello di scaldare il ferro evitando di fondere i componenti. Il processo, la stagnatura, prevede l'aggiunta di stagno sia al filo che alla piazzola da saldare. La pratica \xe8 fondamentale, ma gli errori non sono dannosi per l'elettronica da saldare."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35511717",children:"Discussion Service"}),".\nGli utenti di Hacker News discutono se sia meglio iniziare con strumenti economici o costosi quando si salda: alcuni suggeriscono la regola di Adam Savage \"compra prima l'economico\", mentre i professionisti suggeriscono di trattare alcuni strumenti come materiali di consumo. Gli esperti consigliano di acquistare l'utensile pi\xf9 economico che fa al caso nostro e di investire in utensili di qualit\xe0 se necessario. Mettono in guardia dall'uso di alternative a basso costo e suggeriscono invece marchi affidabili. I consigli includono l'uso del flussante e la scelta di saldature senza piombo; una buona ventilazione e lo smaltimento dei rifiuti sono essenziali. Gli utenti consigliano di investire in saldatori di alta qualit\xe0, flussante chipquik e punte placcate. \xc8 necessario acquisire competenze pratiche e promuovere prodotti di migliore qualit\xe0."]}),"\n",(0,n.jsx)(e.h2,{id:"insegnare-a-chatgpt-a-parlare-la-lingua-inventata-di-mio-figlio",children:"Insegnare a ChatGPT a parlare la lingua inventata di mio figlio"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://szopa.medium.com/teaching-chatgpt-to-speak-my-sons-invented-language-9d109c0a0f05",children:"Originale"}),".\nUn padre e un figlio insegnano a un computer l'esclusiva lingua K\u0142eti attraverso la tecnologia dei chatbot, dimostrando i progressi della tecnologia nel rendere la fantascienza una realt\xe0. La lingua ha un proprio alfabeto e un ordine di parole SOV, rendendo l'uso di copule e particelle cruciale per affinare la comprensione del chatbot. Un esperimento con ChatGPT per tradurre dall'inglese a K\u0142eti ha prodotto traduzioni parzialmente corrette e un punteggio di 6,5 su 12, mostrando il potenziale della traduzione linguistica dell'IA in futuro. L'autore spera che i progressi della tecnologia di traduzione linguistica AI offrano vantaggi sostanziali."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35515208",children:"Discussion Service"}),".\nGli utenti di Discussion Service discutono dell'apprendimento in contesto e della flessibilit\xe0 di ChatGPT, evidenziando al contempo limiti e capacit\xe0; Microsoft potrebbe essere in grado di capitalizzare sul ciclo di feedback umano. Gli esperti mettono in dubbio la comprensione del linguaggio e le limitazioni di ChatGPT per quanto riguarda le emozioni e i giochi. Il GPT-4 mostra un potenziale nell'apprendimento del linguaggio e nell'elaborazione simbolica. Gli utenti riferiscono risultati contrastanti con ChatGPT e GPT-4 in vari compiti."]}),"\n",(0,n.jsx)(e.h2,{id:"\xe8-morto-al-jaffee-il-re-del-fold-in-di-mad-magazine",children:"\xc8 morto Al Jaffee, il re del fold-in di Mad Magazine."}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.nytimes.com/2023/04/10/arts/al-jaffee-dead.html",children:"Originale"}),".\nSpiacente, non c'\xe8 un testo da riassumere perch\xe9 \xe8 stato fornito un riferimento. Si prega di fornire il contenuto del testo da riassumere."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35517629",children:"Discussion Service"}),".\nAl Jaffee, leggenda di Mad Magazine e creatore del fold-in, \xe8 morto a 99 anni. Molti lo hanno pianto, ricordando il suo impatto sul pensiero critico e sull'umorismo. Alcuni hanno sottolineato il problema di distruggere le riviste per fare il fold-in. I fan hanno ricordato la comprensione delle istruzioni e la pubblicazione di Donald Knuth su Mad Magazine. L'impatto di Jaffee sulla cultura popolare \xe8 stato diffuso e apprezzato in tutto il mondo."]}),"\n",(0,n.jsx)(e.h2,{id:"linferno-non-finisce-mai-su-x86-la-storia-delliperspazio-continua-pi\xf9-o-meno",children:"L'inferno non finisce mai su x86: La storia dell'iperspazio, continua, pi\xf9 o meno"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://cohost.org/cathoderaydude/post/1311259-hell-never-ends-on-x",children:"Originale"}),".\nHP ha sostituito il suo Linux istantaneo QuickWeb con una nuova versione basata su Hyperspace. QuickWeb \xe8 stato disponibile su tutte le macchine per diversi anni. I computer portatili HP hanno un pulsante separato, QuickLook, che lancia un'applicazione per la posta elettronica e il calendario. Tuttavia, l'applicazione si basa su un plugin di Outlook e non accede direttamente al file di dati di Outlook. HP ha sfruttato l'SMM per ottenere un risultato che dovrebbe essere impossibile. Dell e i fornitori di schede madri non possono offrire funzionalit\xe0 che vadano oltre i componenti standardizzati. HP ha lottato per differenziare i propri prodotti e offrire \"funzionalit\xe0 per i dirigenti\". Un addetto all'assistenza tecnica ha creato una shell utilizzando il comando efibootmgr di Linux per facilitare l'accesso in caso di guasto del sistema. La maggior parte delle schede madri per PC ha qualcosa di unico, ma queste caratteristiche possono essere applicate solo a utenti di nicchia. L'articolo evidenzia le frustranti esperienze degli utenti con la tecnologia, tra cui le ventole difettose delle GPU HP."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35509175",children:"Discussion Service"}),".\nL'articolo illustra le complessit\xe0 nella scrittura delle applicazioni UEFI e la gestione del comportamento del BIOS in caso di sospensione. Alcuni utenti contestano le affermazioni dell'autore. I produttori di computer portatili espongono funzionalit\xe0 preziose tramite callout ACPI WMI predefiniti. Alcuni considerano Windows gonfio e l'ambiente EFI ha una vaga somiglianza con un MS-DOS a 32/64 bit. Il processo di avvio dei PC x86 \xe8 ancora lento. Si sente la mancanza di pulsanti capacitivi sui portatili. HP ha progettato un sistema operativo senza un proprio scheduler che viene caricato nel TE in fase di esecuzione. Alcuni utenti di Discussion Service discutono se si tratti di un hypervisor o di un gestore di interrupt. Il post ha generato diverse reazioni."]}),"\n",(0,n.jsx)(e.h2,{id:"dobbiamo-parlare-di-vercel",children:"Dobbiamo parlare di Vercel"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.maxcountryman.com/articles/we-need-to-talk-about-vercel",children:"Originale"}),".\nLe recenti discussioni su Vercel hanno messo in evidenza il suo pesante sovrapprezzo rispetto ad AWS Lambda, i costi a sorpresa e le carenze tecniche del suo prodotto Content Delivery Network. Sebbene il valore aggiunto di Vercel possa valere la pena per alcuni, la sua mancanza di supporto e di risposta ai problemi tecnici \xe8 preoccupante. Il CDN di Vercel distorce l'intestazione Cache-Control e non rispetta i valori configurati come pubblicizzato. Le risposte dell'assistenza in prima linea sono state ignorate e l'amministratore delegato di Vercel ha difeso il comportamento come necessario per proteggere gli utenti. AWS investe molto nel successo dei clienti, a differenza di Vercel. Di conseguenza, l'autore si allontaner\xe0 da Vercel."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35507814",children:"Discussion Service"}),".\nUn'indagine su Vercel ha sollevato preoccupazioni per il servizio clienti, i prezzi e i problemi di scalabilit\xe0, suggerendo fornitori alternativi come GitHub Actions, DigitalOcean e Cloudflare. Sono state mosse critiche alla messaggistica ingannevole, alla documentazione inadeguata e agli scarsi tempi di risposta. Alcuni utenti di Next.js discutono sul rendering lato server rispetto alla generazione di siti statici, criticando il design di Vercel e la mancanza di specifiche. Sono state mosse critiche anche ai prezzi, alle pratiche commerciali e alle pratiche di fatturazione di Vercel, suggerendo alternative pi\xf9 economiche come BunnyCDN o R2. Il supporto di Vercel viene criticato, nonostante gli sforzi di marketing. Alcuni lodano l'esperienza degli sviluppatori e le implementazioni per ramo."]}),"\n",(0,n.jsx)(e.h2,{id:"i-filmati-delle-dashcam-mostrano-le-auto-senza-conducente-che-intasano-san-francisco",children:"I filmati delle dashcam mostrano le auto senza conducente che intasano San Francisco"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.wired.com/story/dashcam-footage-shows-driverless-cars-cruise-waymo-clogging-san-francisco/",children:"Originale"}),".\nLe aziende produttrici di veicoli autonomi, tra cui Waymo e Cruise di General Motors, hanno causato ritardi e potenziali pericoli per gli autobus, i treni e i passeggeri di San Francisco a partire dal settembre 2022, con 92 fermate non pianificate che hanno causato notevoli ritardi nei trasporti. Nonostante i tentativi di aggiungere altri robotaxi alle strade di San Francisco, i funzionari della citt\xe0 esprimono preoccupazione per l'aumento del caos causato dai veicoli autonomi ed esortano a compiere progressi nel risolvere i problemi prima di autorizzare le operazioni. I sostenitori dei trasporti di San Francisco propongono misure, come la creazione di corsie riservate al transito e l'imposizione di multe alle aziende che causano ritardi, per ridurre l'impatto dei veicoli autonomi. La San Francisco Municipal Transportation Agency sta discutendo con le aziende di veicoli autonomi per ridurre al minimo i disagi."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35511052",children:"Discussion Service"}),".\nLe riprese dei cruscotti mostrano le auto senza conducente che causano la congestione del traffico a San Francisco. Alcuni temono la tariffazione della congestione, mentre altri vedono un potenziale per le nuove infrastrutture e il trasporto di massa. Le preoccupazioni per le situazioni impreviste e per l'eccesso di auto vuote che intasano le strade esistono; tuttavia, i veicoli autonomi potrebbero ridurre le tariffe e i costi di parcheggio ed eliminare la propriet\xe0 dell'auto. Esistono soluzioni come le stazioni di ricarica e la limitazione della congestione attraverso tariffe e regolamenti. Il potenziale impatto delle auto a guida autonoma sul trasporto pubblico, sulla densit\xe0 urbana, sugli alloggi, sui parcheggi e sui mercati del lavoro \xe8 oggetto di dibattito. Lo scetticismo esiste, ma le possibilit\xe0 sono intriganti. Le auto a guida autonoma potrebbero portare a flotte invece che a singoli proprietari, ottimizzando l'uso e diventando economicamente vantaggiose. La tecnologia a guida autonoma pu\xf2 migliorare il trasporto pubblico e ridurre le emissioni, ma esistono potenziali aspetti negativi. La gestione del traffico in tempo reale, la riduzione dell'inquinamento e i trasporti pi\xf9 economici sembrano promettenti, con la necessit\xe0 di sistemi di trasporto pi\xf9 sicuri ed efficienti. I funzionari di San Francisco incolpano le auto senza conducente per la congestione del traffico, ma gli esperti sostengono il contrario. L'articolo evidenzia i problemi legati alle regole degli autobus e alla tecnologia driverless."]}),"\n",(0,n.jsx)(e.h2,{id:"openbsd-73",children:"OpenBSD 7.3"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.openbsd.org/73.html",children:"Originale"}),".\nLa versione 7.3 di OpenBSD presenta miglioramenti al kernel, aggiornamenti di sistema, mmap sbloccate e supporto hardware. OpenBSD introduce anche varie tecniche di mitigazione e modifiche allo stack di rete per prevenire i crash e migliorare le prestazioni. Il rilascio include varie funzionalit\xe0 userland, correzioni di bug e miglioramenti della sicurezza, come la prevenzione della lettura della memoria e dei binari di sola esecuzione. Inoltre, sono stati aggiunti, migliorati o rielaborati nuovi driver. L'aggiornamento include anche miglioramenti per nc, LibreSSL versione 3.7.2, e OpenSSH 9.3 e 9.2. Il rilascio offre il supporto per il port forwarding remoto dinamico e pacchetti precostituiti per diverse architetture. La mailing ",(0,n.jsx)(e.a,{href:"mailto:listports@openbsd.org",children:"listports@openbsd.org"})," fornisce ulteriori informazioni agli utenti."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35512401",children:"Discussion Service"}),".\nOpenBSD 7.3 \xe8 stato rilasciato con un migliore rilevamento dei bug, pu\xf2 essere usato come NAS/router/server domestico; correzione dell'editor Unix. Secondo un utente di Discussion Service, OpenBSD potrebbe superare Linux. OpenBSD manca di .NET, Mono cerca il supporto BSD. Il filtraggio dei pacchetti di OpenBSD \xe8 filettato, con un hardware modesto in grado di eseguire 1G routing+PF+VLAN. Nessun supporto Bluetooth, manca il driver ENA, il processo di rilascio di OpenBSD discusso da Theo DeRaat."]}),"\n",(0,n.jsx)(e.h2,{id:"personal-concierge-con-chatgpt-di-openai-via-telegram-e-messaggi-vocali",children:"Personal Concierge con ChatGPT di OpenAI via Telegram e messaggi vocali"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://github.com/RafalWilinski/telegram-chatgpt-concierge-bot",children:"Originale"}),".\nUn nuovo bot per Telegram, che utilizza ChatGPT di OpenAI, LangchainJS, Whisper API di OpenAI e Play.ht, consente di offrire servizi di concierge personalizzati sia a voce che in chat. Per utilizzarlo, gli utenti devono acquisire un token bot Telegram e una chiave API OpenAI, quindi seguire i passaggi elencati su GitHub. Il bot \xe8 uno sviluppo nuovo ed entusiasmante per chi cerca servizi di assistenza a mani libere e ha attirato l'attenzione di siti di social media come Twitter e Hacker News."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35510516",children:"Discussion Service"}),".\nUn personal concierge che utilizza ChatGPT ha attirato l'attenzione su Hacker News, dando vita a discussioni sull'efficacia, i prezzi e i potenziali utilizzi. Gli utenti sono interessati a migliorare la produttivit\xe0 grazie all'intelligenza artificiale, ma ci sono preoccupazioni riguardo all'archiviazione dei dati e ai costi elevati. ChatGPT e tecnologie simili vengono integrate in un numero maggiore di progetti, ma ci sono problemi di privacy. OpenAI chiarisce le sue politiche di conservazione dei dati e cerca di proteggerli quando utilizza prodotti di consumo."]}),"\n",(0,n.jsx)(e.h2,{id:"editanything-segmento-di-qualsiasi-cosa--controlnet--blip2--diffusione-stabile",children:"EditAnything: Segmento di qualsiasi cosa + ControlNet + BLIP2 + Diffusione stabile"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://github.com/sail-sg/EditAnything",children:"Originale"}),".\nIl progetto in corso, Edit Anything, utilizza Segment Anything, ControlNet, BLIP2, Stable Diffusion e altro ancora per \"modificare e generare qualsiasi cosa\" nelle immagini, con particolare attenzione ai contributi e ai suggerimenti divertenti. Le caratteristiche includono il controllo a grana fine con ControlNet pre-addestrato e maschere SAM non correlate alla categoria, e il controllo senza guida del testo BLIP2. Gli obiettivi in corso includono l'aggiunta di un controllo interattivo per l'editing delle immagini e l'editing guidato da chatGPT. Le persone interessate possono creare un ambiente seguendo le istruzioni di configurazione fornite e addestrare i propri modelli, oppure utilizzare i modelli pre-addestrati disponibili. Il progetto si basa su diversi altri incredibili progetti, per i quali i creatori esprimono gratitudine."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35509429",children:"Discussion Service"}),'.\nEditAnything" utilizza Segment Anything, ControlNet, BLIP2 e Stable Diffusion. Gli utenti di Discussion Service desiderano una spiegazione di ELI5. Segment Anything convince per la sua precisione. La segmentazione delle immagini \xe8 impressionante. ControlNet fornisce nuove condizioni, insiemi di dati, senza dimenticanze catastrofiche. Il set di dati \xe8 stato generato da esseri umani e automatizzato. Gli esempi non impressionano alcuni individui. Segment Anything funziona con precisione sulle immagini astratte. Gli utenti lodano la tecnologia. Si discute del codice di addestramento e messa a punto.']}),"\n",(0,n.jsx)(e.h2,{id:"agenti-generativi-simulacri-interattivi-del-comportamento-umano",children:"Agenti generativi: Simulacri interattivi del comportamento umano"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://arxiv.org/abs/2304.03442",children:"Originale"}),".\nI ricercatori hanno introdotto gli \"agenti generativi\", agenti software computazionali che simulano un comportamento umano credibile utilizzando un'architettura che estende modelli linguistici di grandi dimensioni per memorizzare un record completo delle esperienze dell'agente utilizzando il linguaggio naturale, sintetizzare queste memorie nel tempo in riflessioni di livello superiore e recuperarle dinamicamente per pianificare il comportamento. In una valutazione, questi agenti generativi producono comportamenti individuali ed emergenti credibili in un ambiente sandbox interattivo ispirato a The Sims. La ricerca introduce modelli architettonici e di interazione per consentire simulazioni credibili del comportamento umano."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35517649",children:"Discussion Service"}),".\nAgenti generativi: Interactive Simulacra of Human Behavior\", un articolo che attira l'attenzione di Discussion Service sulla riduzione del comportamento e sulla programmazione dei bot. La discussione include la \"voce interiore\" e la dipendenza dell'intelligenza profonda dall'ambiente. Vengono citati i limiti dei modelli linguistici, con particolare attenzione agli algoritmi di livello superiore per il controllo. L'intelligenza artificiale \"Dreamer\" di Google suscita un dibattito sul processo decisionale etico. L'esperimento di IA simula agenti alimentati da LLM in una piccola citt\xe0, concentrandosi sullo sviluppo della memoria e della personalit\xe0 e richiedendo una simulazione costosa."]}),"\n",(0,n.jsx)(e.h2,{id:"peste-danzante-del-1518",children:"Peste danzante del 1518"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://en.wikipedia.org/wiki/Dancing_plague_of_1518",children:"Originale"}),".\nNel 1518, un gruppo di 50-400 persone a Strasburgo, in Alsazia, inizi\xf2 a ballare per settimane dopo che una donna aveva iniziato a ballare per strada, ma la causa del fenomeno \xe8 sconosciuta. Le fonti storiche descrivono l'evento come un caso di mania danzante, mentre le teorie moderne suggeriscono un'isteria di massa indotta dallo stress o un'intossicazione alimentare causata da funghi ergot. \xc8 controverso se la peste abbia provocato dei decessi: alcune fonti sostengono che durante l'epidemia abbia ucciso circa 15 persone al giorno. La peste danzante ha ispirato opere di cultura pop, tra cui una canzone di Florence and the Machine."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35509132",children:"Discussion Service"}),'.\nLa peste danzante del 1518 fu causata da balli incontrollati con possibili fattori medici e sociali. Danze incontrollate simili nel corso della storia potrebbero essere dovute a malattie psicogene di massa. La medicina moderna fatica a spiegare questi fenomeni. I commenti discutono i riferimenti storici alla "danza" e ipotizzano le cause della malattia. L\'articolo offre un collegamento a eventi storici intellettualmente stimolanti.']}),"\n",(0,n.jsx)(e.h2,{id:"i-punteggi-del-qi-americano-sono-rapidamente-scesi-a-riprova-delleffetto-flynn-inverso",children:'I punteggi del QI americano sono rapidamente scesi, a riprova dell\'"effetto Flynn inverso".'}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.popularmechanics.com/science/a43469569/american-iq-scores-decline-reverse-flynn-effect/",children:"Originale"}),".\nUna nuova ricerca della Northwestern University suggerisce che i punteggi del QI americano sono in declino dopo decenni di aumenti costanti, noti come \"effetto Flynn\". Lo studio ha esaminato i dati sull'intelligenza dal 2006 al 2018 e ha rilevato che i punteggi in tre dei quattro \"domini cognitivi\" - ragionamento verbale, ragionamento matriciale e serie di lettere e numeri - sono in calo. Tuttavia, i punteggi nel ragionamento spaziale (noto come rotazione 3D) hanno mostrato una tendenza all'aumento. I ricercatori non sono certi delle ragioni alla base di questa tendenza, ma suggeriscono che potrebbe trattarsi di un cambiamento nei valori della societ\xe0, dell'influenza dell'istruzione STEM o di una diminuzione dell'interesse per alcune aree dell'indagine."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35511744",children:"Discussion Service"}),".\nI punteggi del QI americano stanno diminuendo, indicando il cosiddetto \"effetto Flynn inverso\". Le variazioni annuali nei punteggi del QI possono indicare problemi di validit\xe0 della misurazione. Gli utenti di Discussion Service discutono se i punteggi grezzi dei test del QI possano essere confrontati nel tempo e tra i vari test. Gli accademici delle discipline umanistiche lottano per definire il pensiero critico, che non viene pi\xf9 insegnato nelle scuole. L'ereditariet\xe0 del QI viene discussa nella sezione commenti, con alcuni utenti che sottolineano come l'ereditariet\xe0 non significhi necessariamente che siano in gioco fattori genetici o biologici. Gli esperti discutono sul ruolo del QI nella societ\xe0 e nella ricerca sull'intelligenza artificiale. I punteggi del QI nei Paesi sviluppati sono diminuiti a partire dagli anni '70, con possibili fattori che includono i videogiochi e la disuguaglianza di reddito. Non c'\xe8 un chiaro argomento centrale o nuove informazioni significative nei commenti del post."]}),"\n",(0,n.jsx)(e.h2,{id:"usare-il-pio-rp2040-per-pilotare-un-displa-mal-progettato",children:"Usare il PIO RP2040 per pilotare un displa mal progettato"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://dmitry.gr/?r=06.%20Thoughts&proj=09.ComplexPioMachines",children:"Originale"}),".\nDmitry.GR ha sviluppato un driver senza CPU con RP2040 PIO per un display che supporta modalit\xe0 multiple e touch screen. Tuttavia, il display \xe8 mal progettato e il codice di esempio \xe8 impegnativo. Nonostante alcune limitazioni, i dati tattili possono essere copiati in memoria per un ulteriore utilizzo. Un articolo illustra le diverse modalit\xe0 di utilizzo del controller del display, i macchinari DMA e PIO e i problemi di concatenamento DMA. Il display touch pone problemi a causa del rumore e del campionamento improprio e della condivisione di un bus SPI con una scheda SD. La configurazione prevede il bit-banging SPI utilizzando GPIO con API per le funzioni di visualizzazione, con codice BSD con licenza a 2 clausole disponibile per il download e la modifica."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35507933",children:"Discussion Service"}),".\nUn utente di Discussion Service ha condiviso come utilizzare RP2040 PIO per pilotare un display mal progettato con touch sullo stesso bus SPI. Altri utenti hanno discusso di risoluzione temporale, sovracampionamento e DMA. Il post offre dettagli tecnici unici e una nuova soluzione a un vecchio problema. I PIO possono gestire in modo creativo le varie risorse hardware delle periferiche utilizzando in modo efficiente la CPU. I commenti discutono l'overclocking dell'RP2040 e suggeriscono schermi e MCU alternativi."]}),"\n",(0,n.jsx)(e.h2,{id:"algoritmo-di-classificazione-di-hacker-news",children:"Algoritmo di classificazione di Hacker News"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://vigneshwarar.substack.com/p/hackernews-ranking-algorithm-how",children:"Originale"}),".\nL'autore propone un algoritmo di ranking alternativo per Hacker News (Discussion Service), dove l'algoritmo attuale considera solo il numero di upvotes per un link, mentre il nuovo algoritmo considera anche gli upvotes per i commenti. L'algoritmo proposto utilizza il PageRank e una penalit\xe0 di flag per promuovere discussioni sane e profili con punteggi HackerRank pi\xf9 elevati. L'idea principale \xe8 quella di classificare i post non solo in base alla popolarit\xe0 del link, ma anche alla qualit\xe0 della discussione. L'autore invita i lettori a condividere i loro pensieri su come avrebbero progettato l'algoritmo Discussion Service."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35510413",children:"Discussion Service"}),".\nGli utenti discutono i pro e i contro dell'algoritmo di ranking di Hacker News e del PageRank, suggeriscono nuove metriche e la personalizzazione del PageRank, mettono in guardia da potenziali manipolazioni e propongono un grafo bipartito. Alcuni utenti mettono in dubbio la necessit\xe0 del sistema di classificazione/votazione e suggeriscono di dare priorit\xe0 ai commenti di alta qualit\xe0 e a quelli pi\xf9 popolari. La natura ambigua del pulsante upvote suggerisce due dimensioni per la qualit\xe0 e l'allineamento. Alcuni utenti notano le carenze del sistema di classificazione dei commenti e discutono l'individuazione/gestione di post manipolati. L'articolo mette in guardia dalla politicizzazione e incoraggia la curiosit\xe0; \xe8 meglio che Discussion Service rimanga invariato."]}),"\n",(0,n.jsx)(e.h2,{id:"la-chiusura-dellenergia-nucleare-potrebbe-aumentare-linquinamento-atmosferico-uno-studio",children:"La chiusura dell'energia nucleare potrebbe aumentare l'inquinamento atmosferico: uno studio"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://news.mit.edu/2023/study-shutting-down-nuclear-power-could-increase-air-pollution-0410",children:"Originale"}),".\nLa chiusura delle centrali nucleari statunitensi potrebbe aumentare l'inquinamento atmosferico di oltre 5.000 morti, hanno avvertito i ricercatori del MIT. L'aumento dell'inquinamento sar\xe0 dovuto all'utilizzo di carbone, petrolio e gas. Le fonti rinnovabili che sostituiscono le centrali nucleari, invece, potrebbero ridurre i decessi legati all'inquinamento. La comunit\xe0 nera sar\xe0 maggiormente esposta all'aumento dell'inquinamento, poich\xe9 questi gruppi tendono a vivere pi\xf9 vicino alle centrali a combustibili fossili. Lo studio del MIT indica che la qualit\xe0 dell'aria non \xe8 stata pienamente affrontata nelle conversazioni sulla chiusura delle centrali nucleari."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35518032",children:"Discussion Service"}),".\nUno studio del MIT rivela che la chiusura delle centrali nucleari potrebbe portare a un aumento dell'inquinamento atmosferico. I commentatori di Hacker News sono divisi sul grado e sulla natura dell'inquinamento atmosferico causato dal nucleare, confrontando gli Stati Uniti con altri Paesi. Le opinioni sull'energia nucleare sono polarizzate e riguardano l'inquinamento radioattivo, la regolamentazione e la sicurezza, ma alcuni la considerano un'opzione pi\xf9 pulita ed efficiente dei combustibili fossili. \xc8 necessario investire nelle energie rinnovabili e in una strategia energetica a lungo termine. Si discute del potenziale dell'energia da fusione e si esprime preoccupazione per la forte dipendenza della Cina dalla catena di approvvigionamento solare."]}),"\n",(0,n.jsx)(e.h2,{id:"il-crollo-delle-spedizioni-di-pc-da-parte-di-apple-\xe8-il-pi\xf9-forte-tra-i-principali-produttori-di-computer",children:"Il crollo delle spedizioni di PC da parte di Apple \xe8 il pi\xf9 forte tra i principali produttori di computer"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.bloomberg.com/news/articles/2023-04-10/apple-s-40-plunge-leads-pc-shipments-down-as-tech-demand-sags",children:"Originale"}),".\nLe spedizioni di PC di Apple hanno subito un calo del 40,5%, il maggiore dal 2000, a causa della domanda fiacca e dell'eccesso di offerta nel settore. Questo calo ha contribuito a un crollo complessivo del 29% delle spedizioni di PC tra i principali marchi, a causa dell'attenuazione dell'aumento della domanda di lavoro a distanza, dovuta alle restrizioni imposte dalla pandemia. Lenovo e Dell hanno registrato cali superiori al 30% e nessun marchio importante \xe8 stato risparmiato dal rallentamento. L'introduzione del vaccino COVID-19 e il calo delle tendenze del lavoro a distanza potrebbero favorire l'abbandono dei PC, ma non \xe8 chiaro se questa tendenza continuer\xe0 a lungo termine."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35510612",children:"Discussion Service"}),".\nApple registra un calo significativo delle spedizioni di PC, ma la domanda di modelli M1 \xe8 aumentata durante la pandemia. L'aumento delle prestazioni dei modelli M1 \xe8 stato incrementale, con l'Air che ha fatto registrare il salto pi\xf9 significativo. Gli utenti sono riluttanti a effettuare l'aggiornamento a causa della maggiore durata della batteria dei modelli M1 e del fatto che per un po' di tempo non sar\xe0 necessario effettuare l'aggiornamento. Le spedizioni di Mac sono aumentate, ma alcuni utilizzano ancora modelli precedenti al 2016 o la patch Catalina. La memoria saldata aumenta le prestazioni, mentre l'archiviazione saldata rappresenta una limitazione dello spazio di archiviazione. Gli assegni di incentivazione sono correlati a un aumento delle vendite di Macbook. Opinioni diverse sull'opportunit\xe0 di aggiornare e utilizzare i prodotti Apple alla luce dei fattori economici e tecnologici. Politiche di prezzo dei MacBook criticate perch\xe9 troppo elevate. I MacBook sono lodati per la loro longevit\xe0 e Asahi Linux \xe8 un'ottima opzione per chi preferisce un sistema operativo orientato al lavoro."]}),"\n",(0,n.jsx)(e.h2,{id:"se-hai-raccolto-capitale-di-rischio-devi-pagarti-da-solo",children:"Se hai raccolto capitale di rischio, devi pagarti da solo"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://techcrunch.com/2023/04/09/f-you-pay-me/",children:"Originale"}),".\nQuesto non \xe8 il testo corretto per il riassunto, poich\xe9 \xe8 solo un messaggio di errore. Non \xe8 necessario un riassunto."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35512081",children:"Discussion Service"}),".\nGli utenti di Discussion Service discutono degli stipendi dei fondatori dopo il finanziamento con capitale di rischio. Viene suggerito un sistema di retribuzione graduale basato sulla crescita dei ricavi. I dipendenti non fondatori potrebbero non beneficiare delle azioni come le aziende consolidate. Le cooperative sono suggerite come un modo per condividere le ricompense. Alcuni dipendenti sopravvalutano l'equity della startup. Il CEO di una startup raccomanda di pagarsi abbastanza per concentrarsi sulla crescita dell'azienda. I fondatori sono incoraggiati a pagare i dipendenti pi\xf9 vicino al prezzo di mercato. \xc8 difficile bilanciare la stabilit\xe0 finanziaria dell'azienda con una retribuzione ragionevole. Pagarsi in modo equo \xe8 un dovere, ma avviare un'impresa redditizia in regime di startup \xe8 rischioso. I fondatori dovrebbero evitare il burnout pagando uno stipendio che imiti quello di un dipendente. Si consiglia cautela con il capitale di rischio. I fondatori dovrebbero essere ricompensati in modo generoso se lo stipendio non prosciuga eccessivamente i fondi dell'azienda. Vengono discusse le esperienze personali in materia di retribuzione e investimenti in startup. I dipendenti del settore tecnologico dovrebbero concentrarsi su ci\xf2 che \xe8 meglio per loro."]}),"\n",(0,n.jsx)(e.h2,{id:"il-fiume-kissimmee-\xe8-stato-riportato-in-vita-e-la-fauna-selvatica-sta-prosperando",children:"Il fiume Kissimmee \xe8 stato riportato in vita e la fauna selvatica sta prosperando."}),"\n",(0,n.jsxs)(e.p,{children:["(",(0,n.jsx)(e.a,{href:"https://www.nationalgeographic.com/environment/article/kissimmee-biggest-river-restoration-ever-completed",children:"https://www.nationalgeographic.com/environment/article/kissimmee-biggest-river-restoration-ever-completed"}),").\nIl fiume Kissimmee, in Florida, \xe8 stato riportato al suo stato naturale dopo decenni di deviazione in un canale rettilineo, che porta con s\xe9 una serie di animali selvatici. Le pianure alluvionali serpeggianti del fiume ospitavano un tempo zone umide stagionali ricche di vita, ma negli anni '40 furono convertite in una rete di canali e corsi d'acqua dal Corpo degli Ingegneri dell'Esercito. Da allora, tuttavia, il fiume \xe8 stato riportato alla sua forma originale e le varie specie di uccelli, mammiferi e pesci stanno lentamente ma inesorabilmente tornando."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35508677",children:"Discussion Service"}),".\nIl fiume Kissimmee \xe8 stato sottoposto a un costoso restauro e la fauna selvatica sta prosperando. Gli utenti raccomandano il documentario \"Path of the Panther\". Il governatore DeSantis \xe8 stato criticato per le sue politiche in materia di ambiente e cambiamenti climatici. Nonostante la produzione di gas naturale, la Florida d\xe0 priorit\xe0 alla gestione dell'acqua e delle zone umide. Le perdite di energia nucleare in Florida rendono diffidenti gli elettori. FPL colta in flagrante comportamento politico non etico. La ricchezza nella met\xe0 vulnerabile, le risorse mancano. Le entrate fiscali della Florida. Preoccupazione per l'allocazione del bilancio. Le politiche dell'EPA favoriscono le grandi imprese. Non si conosce il rapporto costo-efficacia del drenaggio dei terreni."]}),"\n",(0,n.jsx)(e.h2,{id:"usare-le-azioni-github-per-rendere-dinamico-il-profilo-github",children:"Usare le azioni GitHub per rendere dinamico il profilo GitHub"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.bengreenberg.dev/posts/2023-04-09-github-profile-dynamic-content/",children:"Originale"}),".\nGli utenti di GitHub possono rendere dinamico il proprio profilo utilizzando GitHub Actions, creando un repository con un file README.md contenente le informazioni desiderate sul profilo, aggiungendo cartelle per i contenuti dinamici e aggiungendo una nuova sottocartella per lo script che esegue lo scraping dei dati da un sito web e modificandolo nel file README.md; il contenuto del profilo si trova andando su github.com/[nomeutente] in un browser web, con il repository che \xe8 la fonte della pagina del profilo; la nuova sottocartella per il flusso di lavoro \xe8 installata in [workflows] all'interno della directory principale e viene impostata una pianificazione per eseguire lo script una volta alla settimana; gli utenti possono utilizzare diversi linguaggi, tra cui Ruby, TypeScript, JavaScript e Python per creare un profilo dinamico; questa tecnica migliora il profilo GitHub di un individuo, rendendolo un esempio pi\xf9 dinamico e in continua evoluzione."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35514799",children:"Discussion Service"}),".\nUn post di Hacker News parla dei profili dinamici di GitHub tramite GitHub Actions. I commenti variano dallo scetticismo alle lodi."]}),"\n",(0,n.jsx)(e.h2,{id:"quello-che-ho-imparato-sui-metodi-formali-in-mezzo-anno",children:"Quello che ho imparato sui metodi formali in mezzo anno"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://jakob.space/blog/what-ive-learned-about-formal-methods.html",children:"Originale"}),".\nL'autore condivide la propria esperienza di apprendimento dei metodi formali e dell'uso di tecniche matematiche per verificare le propriet\xe0 del software. L'articolo discute i vantaggi dei metodi formali, compresi quelli leggeri come Alloy e Forge, e fornisce un esempio di utilizzo di Alloy per verificare l'implementazione di un file system. Esplora i diversi approcci agli assistenti di prova, come Lean, e i vantaggi e gli svantaggi del loro utilizzo. L'articolo discute anche la semantica dei linguaggi di programmazione e il significato di raffinatezza nella matematica legata alla verifica del software, mostrando la conoscenza e l'uso di Lean da parte dell'autore. Inoltre, l'autore spiega il concetto di metodi formali e fornisce una panoramica delle tecniche di verifica adatte ai sistemi di alto e basso livello. Il post pu\xf2 interessare gli esperti di programmazione e informatica."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35511152",children:"Discussion Service"}),".\nUn utente di Discussion Service condivide le proprie conoscenze sui metodi formali, mentre i commentatori forniscono le loro esperienze e opinioni. Frama-C e SPARK sono consigliati, insieme a TLA+ per un avvio rapido. I metodi formali sono utili per la verifica dell'hardware, ma sono di nicchia per la maggior parte del software. I test dei contratti e l'analisi del flusso di dati aiutano a prevenire gli errori di avvio. Sistemi di intelligenza artificiale come ChatGPT possono convalidare il codice rispetto ai requisiti del sistema. La notazione matematica \xe8 pi\xf9 efficiente delle espressioni in linguaggio naturale nelle prove formali. La democratizzazione della conoscenza \xe8 fondamentale nell'industria tecnologica."]}),"\n",(0,n.jsx)(e.h2,{id:"llm-open-source-per-uso-commerciale",children:"LLM open source per uso commerciale?"}),"\n",(0,n.jsx)(e.p,{children:"Un utente di Discussion Service ha chiesto se \xe8 possibile utilizzare legalmente uno strumento LLM open source per uso commerciale. Alcuni utenti hanno consigliato di verificare la licenza specifica dello strumento. Altri hanno suggerito di contattare un avvocato o di utilizzare uno strumento alternativo con licenza commerciale. Un utente ha sottolineato che l'uso dell'open source per scopi commerciali \xe8 possibile con alcune licenze, ma \xe8 essenziale rispettare i termini della licenza."}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35512338",children:"Discussion Service"}),".\nUn utente di Discussion Service cerca un LLM commerciale open source per il suo progetto di ML. I modelli Flan hanno prestazioni leggermente peggiori di GPT-3/4. Sono disponibili altri modelli open-source, ma la formazione \xe8 costosa. Nvidia dovrebbe rilasciare i modelli di base iniziali per gli LLM. Le aziende possono pubblicare modelli di base, ma il vero valore \xe8 a 5-10 livelli superiori. OpenAI non utilizza i dati dei clienti per addestrare i modelli, ma alcune aziende hanno bisogno di segretezza. I modelli di apprendimento automatico probabilmente non sono protetti da diritti di propriet\xe0 intellettuale. Le alternative GPT come BERT e le serie opt possono essere messe a punto a basso costo. Il team GPT4all lavora alla formazione di GPT-J come alternativa aperta. Esistono preoccupazioni sulla responsabilit\xe0 degli LLM."]}),"\n",(0,n.jsx)(e.h2,{id:"scatterplot-animati-e-zoomabili-nel-browser-con-una-scala-di-oltre-un-miliardo-di-punti",children:"Scatterplot animati e zoomabili nel browser, con una scala di oltre un miliardo di punti."}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://github.com/nomic-ai/deepscatter",children:"Originale"}),".\nDeep Scatterplots for the Web \xe8 una libreria in evoluzione per la visualizzazione di grandi quantit\xe0 di dati ad alte prestazioni utilizzando il formato ",(0,n.jsx)(e.code,{children:"feather"})," di Apache Arrow e WebGL. La libreria gestisce anche la maggior parte delle trasformazioni grammaticali della grafica sulla GPU, consentendo transizioni interpolate con calcoli in parallelo. Gli esempi includono oltre un milione di documenti da arxiv.com e ogni persona nei censimenti degli Stati Uniti del 2010 e del 2020, tra gli altri. La libreria viene eseguita in impostazioni completamente statiche che possono essere ospitate su pagine Github. L'API imita Vega-Lite e la libreria offre metodi di jitter come cerchio, spirale e tempo."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35511139",children:"Discussion Service"}),".\nGli scatterplot animati e zoomabili di Nomic AI scalano pi\xf9 di un miliardo di punti nel browser tramite webGPU e i problemi su GitHub sono benvenuti; tuttavia, la mappa di sfondo potrebbe non essere sempre accurata e Highcharts ha un modulo simile ma con meno punti. Anche Nomic AI ha rilasciato gpt4all e librerie come GRAPE e nodevectors potrebbero dare risultati migliori per le incorporazioni in scala. Gli appassionati di visualizzazione potrebbero essere interessati a Galapix, Pix-image-viewer e GGVec, ma potrebbero sorgere problemi di rendering con i dispositivi mobili."]})]})}function u(i={}){const{wrapper:e}={...(0,t.R)(),...i.components};return e?(0,n.jsx)(e,{...i,children:(0,n.jsx)(d,{...i})}):d(i)}}}]);